import {ROSTER,getCharacter} from './roster.js';
import {COURT_SCHEMES} from './court-schemes.js';
import {Tournament,TOURNAMENT_ROUNDS,loadTournament,saveTournament} from './tournament.js';
const $=s=>document.querySelector(s),make=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;};
export function setupTournamentUI({storage,getHuman,getConfig,onOpen,onPlay}){
 let model=loadTournament(storage),draft=[],activeModel=null,activeId=null;const overlay=$('#tournamentModal'),form=$('#tournamentSetup'),bracket=$('#tournamentBracket'),feedback=$('#tournamentFeedback');
 function save(){const ok=saveTournament(storage,model);$('#tournamentSaveNote').textContent=ok?'Bracket saved on this device. A match in progress restarts if you reload.':'This browser cannot save the bracket. Keep this page open.';$('#bracketButton').hidden=false;}
 function seedDraft(){const human=getHuman(),others=ROSTER.filter(p=>p.id!==human).map(p=>p.id);for(let i=others.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[others[i],others[j]]=[others[j],others[i]];}draft=[human,...others.slice(0,7)];}
 function renderSetup(){form.hidden=false;bracket.hidden=true;feedback.textContent='';$('#tournamentBack').hidden=!model;const fields=$('#tournamentEntrants');fields.replaceChildren();draft.forEach((id,i)=>{const label=make('label',i===0?'Your player':`Player ${i+1}`),select=make('select');select.setAttribute('aria-label',i===0?'Tournament human player':`Tournament player ${i+1}`);select.disabled=i===0;for(const p of ROSTER){const option=make('option',`${p.name} · ${p.average}`);option.value=p.id;select.append(option);}select.value=id;select.onchange=()=>{draft[i]=select.value;};label.append(select);fields.append(label);});const c=getConfig();$('#tournamentFormat').textContent=`${c.gamesToSet}-game sets · ${c.bestOf===1?'one set':'best of '+c.bestOf+' sets'} · seven different courts assigned by the tournament. Change the format in Players & match settings.`;}
 function renderBracket(){form.hidden=true;bracket.hidden=false;feedback.textContent='';model.simulateReady();save();const next=model.nextHumanMatch(),champion=model.champion;$('#tournamentStatus').textContent=champion?(champion===model.human?'Tournament champion!':`${getCharacter(champion).name} wins the tournament.`):model.eliminated?'Your tournament is complete.':next?`${TOURNAMENT_ROUNDS.find(r=>r.ids.includes(next.id)).name} · your next match`:'Waiting for the next round';const holder=$('#bracketGrid');holder.replaceChildren();for(const round of TOURNAMENT_ROUNDS){const col=make('div',null,'bracket-round');col.append(make('h2',round.name));const matches=make('div',null,'bracket-matches');for(const id of round.ids){const pair=model.participants(id),result=model.results[id],card=make('article',null,'bracket-match'+(next?.id===id?' bracket-next':''));card.setAttribute('aria-label',round.name+' '+id);card.append(make('p',COURT_SCHEMES[model.courtFor(id)].name,'bracket-court'));for(const [i,p]of pair.entries()){const row=make('div',null,'bracket-player'+(p===result?.winnerId?' bracket-winner':''));row.append(make('span',p?getCharacter(p).name:'Awaiting winner'));if(p===model.human)row.append(make('small','You'));if(p===result?.winnerId)row.append(make('span','✓'));card.append(row);}if(result){card.append(make('p',`${result.score}${result.simulated?' · simulated':''}`,'bracket-score'));}else card.append(make('p',pair.every(Boolean)?'Ready to play':'Previous match pending','bracket-score'));matches.append(card);}col.append(matches);holder.append(col);}const play=$('#tournamentPlay');play.hidden=!next;play.textContent=next?`Play ${next.id[0]==='q'?'quarterfinal':next.id[0]==='s'?'semifinal':'final'} vs ${getCharacter(model.participants(next.id).find(id=>id!==model.human)).name}`:'';}
 function open(){onOpen();if(model)renderBracket();else{seedDraft();renderSetup();}overlay.classList.remove('hidden');}
 $('#tournamentShuffle').onclick=()=>{seedDraft();renderSetup();};$('#tournamentNew').onclick=()=>{seedDraft();renderSetup();};$('#tournamentBack').onclick=renderBracket;
 $('#tournamentCreate').onclick=()=>{try{model=new Tournament({entrants:draft,config:getConfig()});renderBracket();}catch(error){feedback.textContent=error.message;}};
 $('#tournamentPlay').onclick=()=>{const fixture=model.nextHumanMatch();if(!fixture)return;overlay.classList.add('hidden');const resume=activeModel===model&&activeId===fixture.id;activeModel=model;activeId=fixture.id;onPlay({resume,id:fixture.id,court:model.courtFor(fixture.id),human:model.human,opponent:model.participants(fixture.id).find(id=>id!==model.human),config:model.config});};
 $('#bracketButton').hidden=!model;$('#bracketButton').onclick=open;
 return {open,complete(id,match){if(!model||model.results[id])return false;const pair=model.participants(id),winnerId=match.winner===0?model.human:pair.find(id=>id!==model.human),score=match.completedSets.map(s=>{const orient=pair[0]===model.human?s:[s[1],s[0]];return orient.join('–');}).join(', ');model.record(id,winnerId,score||'Match complete');model.simulateReady();save();return true;},get model(){return model;}};
}
